import{_ as a,o as i,c as r,a3 as c}from"./chunks/framework.Ch_0qWu9.js";const v=JSON.parse('{"title":"Graphviz 15.0.0 EPL-2.0 材料","description":"","frontmatter":{"sourcePath":"docs/environments/lean-base/graphviz-epl/README.zh-CN.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/aab56977addd5d217972b7f35cf50be4440cb6c7/docs/environments/lean-base/graphviz-epl/README.zh-CN.md","alternateUrl":"/TCSExam/docs/environments/lean-base/graphviz-epl/","alternateAnchors":{"graphviz-15-0-0-epl-2-0-材料":"graphviz-15-0-0-epl-2-0-materials","graphviz-1500-epl-20-materials":"graphviz-1500-epl-20-materials"}},"headers":[],"relativePath":"zh/environments/lean-base/graphviz-epl/index.md","filePath":"zh/environments/lean-base/graphviz-epl/index.md"}'),p={name:"zh/environments/lean-base/graphviz-epl/index.md"};function o(d,e,l,s,n,t){return i(),r("div",null,[...e[0]||(e[0]=[c('<p><a id="graphviz-1500-epl-20-materials"></a></p><p><a id="graphviz-1500-epl-20-材料"></a></p><h1 id="graphviz-15-0-0-epl-2-0-材料" tabindex="-1">Graphviz 15.0.0 EPL-2.0 材料 <a class="header-anchor" href="#graphviz-15-0-0-epl-2-0-材料" aria-label="Permalink to &quot;Graphviz 15.0.0 EPL-2.0 材料&quot;">​</a></h1><p>中文译文供参考，许可条款以原文为准。</p><p>ProofWidgets 提交 <code>b1436dc749e722c9920036b52cdc43b3451d0b69</code> 提供 Lean 镜像内生成的浏览器文件。这些文件以 WebAssembly 形式嵌入 Graphviz 15.0.0，其 SHA-256 为 <code>b73447cdf82c85bc61be2ebb78f1ac17a70fb7567c9f739268d7542e88cc421c</code>。</p><p>Graphviz 使用 EPL-2.0。<code>@hpcc-js/wasm</code> 2.34.2 封装层单独采用 Apache-2.0。封装层许可不覆盖 Graphviz。</p><p>先阅读 <a href="/TCSExam/docs/zh/environments/lean-base/graphviz-epl/SOURCE-OFFER/">SOURCE-OFFER.md</a>，了解对应源码声明、已验证的归档哈希值、官方源码 URL 和重建路径。完整 Graphviz 和封装层及构建源码归档随镜像保存在 <code>source/</code> 中；获取这些源码材料无需网络访问。</p><p>内容：</p><ul><li><code>EPL-2.0.txt</code>：从已验证的 Graphviz 归档中提取的 Graphviz 许可证。</li><li><code>WRAPPER-APACHE-2.0.txt</code>：从已验证的封装层归档中提取的封装层许可证。</li><li><a href="/TCSExam/docs/zh/environments/lean-base/graphviz-epl/SOURCE-OFFER/"><code>SOURCE-OFFER.md</code></a>：如何获取和检查对应源码。</li><li><code>source-manifest.json</code>：机器可读的版本、URL、字节数和哈希值。</li><li><code>source/</code>：Graphviz 15.0.0 和 <code>hpcc-js-wasm</code> 提交 <code>8b86e2f83cc7344aca44fb3d8aa29a227358c5c4</code> 的完整固定源码归档。</li><li><code>build-rules/</code>：同一封装层归档中构建规则、Graphviz 封装层 C++ 源码和 Graphviz overlay 修改的可读副本。</li><li><code>SHA256SUMS</code>：除校验和文件自身外，已安装文件的哈希值。</li></ul><p>这些材料随生成的 Graphviz JavaScript 和 WebAssembly 一并提供。其他浏览器依赖的来源和声明见单独的浏览器组件及 npm 清单。</p>',10)])])}const m=a(p,[["render",o]]);export{v as __pageData,m as default};
